const items = $input.all();
const originalQuery = $('Init State').item.json.originalQuery;

return [{
  json: {
    rerankBody: {
      model: "rerank-v3.5",
      query: originalQuery,
      documents: items.map(i => i.json.content),
      top_n: 5
    },
    candidates: items.map(i => ({
      id: i.json.id,
      content: i.json.content,
      metadata: i.json.metadata,
      hybrid_score: i.json.score,
      dense_rank: i.json.dense_rank ?? null,
      sparse_rank: i.json.sparse_rank ?? null,
      dense_score: i.json.dense_score ?? null,
      sparse_score: i.json.sparse_score ?? null,
      chunk_index: i.json.metadata?.chunk_index
    }))
  }
}];

const results = $json.results;
const candidates = $('Build Rerank Input').item.json.candidates;

return results.map((r, position) => ({
  json: {
    rank: position + 1,
    id: candidates[r.index].id,
    chunk_index: candidates[r.index].chunk_index,
    content: candidates[r.index].content,
    metadata: candidates[r.index].metadata,
    hybrid_score: candidates[r.index].hybrid_score,
    dense_rank: candidates[r.index].dense_rank,
    sparse_rank: candidates[r.index].sparse_rank,
    dense_score: candidates[r.index].dense_score,
    sparse_score: candidates[r.index].sparse_score,
    relevance_score: r.relevance_score
  }
}));

