parameters.jsCode:
const chunks = $input.all();

return [{
  json: {
    chunks_text: chunks.map((c, i) => 
      `[${i+1}] (id=${c.json.id}, chunk_index=${c.json.chunk_index}, score=${c.json.relevance_score.toFixed(3)})\n${c.json.content}`
    ).join('\n\n'),
    chunks_array: chunks.map(c => c.json),
    chunk_count: chunks.length
  }
}];

const raw = $json.content[0].text.trim();

// Strip markdown fences
let cleaned = raw.replace(/^```(?:json)?\s*/, '').replace(/```\s*$/, '').trim();

// Prefill case: response may start mid-JSON
if (!cleaned.startsWith('{')) {
  cleaned = '{"relevant":' + cleaned;
}

// Find first complete JSON object, ignoring trailing content
const firstBrace = cleaned.indexOf('{');
let depth = 0, endIdx = -1;
for (let i = firstBrace; i < cleaned.length; i++) {
  if (cleaned[i] === '{') depth++;
  else if (cleaned[i] === '}') {
    depth--;
    if (depth === 0) { endIdx = i; break; }
  }
}

const jsonText = endIdx >= 0 ? cleaned.slice(firstBrace, endIdx + 1) : cleaned;

let parsed;
try {
  parsed = JSON.parse(jsonText);
} catch (e) {
  parsed = { 
    relevant: false, 
    reason: 'Grader output not parseable: ' + raw.slice(0, 200) 
  };
}

// Handle both schemas: old {relevant, reason} and new {relevant, evidence, reason}
let reason = parsed.reason;
if (!reason && Array.isArray(parsed.evidence)) {
  reason = `Evidence: ${parsed.evidence.slice(0, 3).join(' | ')}`;
}

return [{
  json: {
    relevant: Boolean(parsed.relevant),
    reason: reason || 'no reason given',
    evidence: parsed.evidence || null,
    raw_grader: raw
  }
}];

// Use n8n's execution-scoped static data — persists across loop iterations
const current = $execution.customData.get('retryCount');
const newCount = (current ? Number(current) : 0) + 1;
$execution.customData.set('retryCount', String(newCount));

// Pass through the input data unchanged, just add retryCount for downstream visibility
return $input.all().map(item => ({
  json: {
    ...item.json,
    retryCount: newCount
  }
}));

const initState = $('Init State').item.json;
const routeData = $('Router JSON Output').item.json;
const finalAnswer = $json.output ?? $json.content?.[0]?.text ?? '';
let finalPath = 'unknown';
let citationCount = 0;

if (routeData.decision === 'DIRECT') {
  finalPath = 'direct_answer';
} else {
  const citationMatches = finalAnswer.match(/\[\d+\]/g) ?? [];
  citationCount = citationMatches.length;
  finalPath = citationCount > 0 ? 'generator' : 'give_up';
}

let retrievedIds = null;
let retrievedChunks = null;
let topScore = null;
let graderVerdict = null;
let graderReason = null;
let rewrittenQueries = null;

if (routeData.decision === 'RETRIEVE') {
  try {
    const reranked = $('Format Reranked').all();
    retrievedIds = reranked.map(r => Number(r.json.id));
    topScore = Math.max(...reranked.map(r => r.json.relevance_score));
    retrievedChunks = reranked.map(r => ({
      id: r.json.id,
      chunk_index: r.json.chunk_index,
      rank: r.json.rank,
      relevance_score: r.json.relevance_score,
      hybrid_score: r.json.hybrid_score,
      dense_rank: r.json.dense_rank,
      sparse_rank: r.json.sparse_rank,
      dense_score: r.json.dense_score,
      sparse_score: r.json.sparse_score,
      content: r.json.content
    }));
  } catch (e) {}

  try {
    const grader = $('Parse Grader Output').item.json;
    graderVerdict = grader.relevant;
    graderReason = grader.reason;
  } catch (e) {}

  try {
    const staticData = $getWorkflowStaticData('global');
    rewrittenQueries = Array.isArray(staticData.rewrites) ? [...staticData.rewrites] : [];
  } catch (e) {
    rewrittenQueries = [];
  }
}

const startedAt = Number(initState.started_at);
const totalLatencyMs = Date.now() - startedAt;
const retryCount = Number($execution.customData.get('retryCount') ?? 0);

return [{
  json: {
    session_id: initState.sessionId ?? null,
    original_query: initState.originalQuery,
    rewritten_queries: rewrittenQueries,
    route_decision: routeData.decision,
    route_reason: routeData.reason ?? routeData.reasoning ?? null,
    retrieved_chunk_ids: retrievedIds,
    retrieved_chunks: retrievedChunks,
    retrieval_top_score: topScore,
    retry_count: retryCount,
    grader_verdict: graderVerdict,
    grader_reason: graderReason,
    final_path: finalPath,
    final_answer: finalAnswer,
    citation_count: citationCount,
    total_latency_ms: totalLatencyMs,
    metadata: {
      n8n_execution_id: $execution.id ?? null
    }
  }
}];

const newRewrite = $json.content?.[0]?.text?.trim() ?? '';

const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.rewrites)) {
  staticData.rewrites = [];
}
staticData.rewrites.push(newRewrite);

return $input.all();

const embedding = $json.data[0].embedding;
const embeddingString = '[' + embedding.join(',') + ']';

return [{
  json: {
    embedding_string: embeddingString
  }
}];
